style.css:
@-moz-document domain("pinterest.com") {
/* 1. FONDO DE LA PÁGINA: Rosa Pastel con Círculos Blancos */
    body, html, #initial-focus-container, [data-test-id="grid"], .App, main {
        background-color: #FFDEE9 !important; /* El tono rosa pastel base */
        background-image: radial-gradient(#FFFFFF 20%, transparent 20%),
                          radial-gradient(#FFFFFF 20%, transparent 20%) !important;
        background-size: 30px 30px !important; /* Controla el tamaño de los círculos */
        background-position: 0 0, 15px 15px !important; /* Alinea los círculos ordenados */
    }

    /* 2. TEXTOS E INFORMACIÓN DE LOS PINES: Amarillo Pollito */
    h1, h2, h3, div, span, p, [data-test-id="pin-title"], [data-test-id="official-user-name"] {
        color: #FFF59D !important;
        /* Le añadimos un borde oscuro muy fino al texto para que el amarillo pollito se lea claro sobre el fondo rosa */
        text-shadow: -1px -1px 0 #4A4A4A, 1px -1px 0 #4A4A4A, -1px 1px 0 #4A4A4A, 1px 1px 0 #4A4A4A !important;
    }

    /* 3. ICONOS GENERALES (Lupita, Mensajes): Blanco puro para que contrasten */
    svg, path, [role="img"] {
        fill: #FFFFFF !important;
        color: #FFFFFF !important;
    }

    /* ======================================================= */
    /* ¡ZONA SANRIO! REEMPLAZO DE ICONOS CON IMÁGENES        */
    /* ======================================================= */

    /* LA CASITA DE INICIO POR HELLO KITTY */
    a[href="/"] svg, a[data-test-id="today-tab"] svg {
        display: none !important;
    }
    a[href="/"]::before {
        content: "" !important;
        display: inline-block !important;
        width: 32px !important;
        height: 32px !important;
        background-image: url('https://icons8.com') !important;
        background-size: contain !important;
        background-repeat: no-repeat !important;
    }

    /* EL ICONO DE TU PERFIL POR MY MELODY */
    a[href*="/_saved/"] svg, a[href*="/profile/"] svg, [data-test-id="HeaderAlpha-ProfileButton"] svg {
        display: none !important;
    }
    a[href*="/_saved/"]::before, a[href*="/profile/"]::before, [data-test-id="HeaderAlpha-ProfileButton"]::before {
        content: "" !important;
        display: inline-block !important;
        width: 32px !important;
        height: 32px !important;
        background-image: url('https://icons8.com') !important;
        background-size: contain !important;
        background-repeat: no-repeat !important;
        margin-top: 4px !important;
    }
}
